// Массив с объектами
const fruits = [
  { name: 'apple', price: 50 },
  { name: 'banana', price: 20 },
  { name: 'cherry', price: 300 },
  { name: 'kiwi', price: 80 }
];

// let для накопителей
let expensiveFruits = [];
let totalPrice = 0;

// Цикл for
for (let i = 0; i < fruits.length; i++) {
  const fruit = fruits[i];

  // if / else
  if (fruit.price > 70) {
    expensiveFruits.push(fruit.name);
  } else {
    // ничего
  }

  totalPrice = totalPrice + fruit.price;
}

// Возврат объекта с полем payload
return [
  {
    json: {
      payload: {
        student: 'vauchkevich',
        expensiveFruits: expensiveFruits,
        totalPrice: totalPrice,
        totalItems: fruits.length
      }
    }
  }
];
